    print(f"{cid}: room open→best {(co-cb)/co*100:5.1f}%  c_open={co:,.0f} c_best={cb:,.0f} c_alt={ca}  alt_score={alt_score if alt_score is None else round(max(min(alt_score,1),0),2)}  our best={best:.2f}  plays={[(x[5],x[6],round(x[3] or 0,2)) for x in room[cid]]}")
